<script setup>
import{ref,reactive,watch}from'vue';
import{requestApi}from'../../../../shared/infrastructure/http/apiClient.js';
import{submitOperation,pendingOperations,retryOperation,reconcilePending}from'../../../../shared/infrastructure/http/pendingOperation.js';
const props=defineProps({lot:Object,identity:Object,online:Boolean}),emit=defineEmits(['refresh']);
const data=ref(null),concessions=ref([]),error=ref(''),notice=ref(''),busy=ref(false),pending=ref([]),latitude=ref(''),longitude=ref(''),concessionId=ref(''),reason=ref('');
const registry=reactive({name:'',source:'',authorizationRef:'',vertices:'',confirmAuthorization:false});
const can=p=>props.identity.permissions.includes(p),scope=()=>({tenantId:props.identity.tenantId,userId:props.identity.userId,resourceId:props.lot.lotId});
const labels={Inside:'Ubicación dentro del polígono autorizado',Outside:'Ubicación fuera del polígono autorizado',PendingCheck:'Ubicación pendiente de comprobación'};
async function load(){if(!props.online)return;try{[data.value,{concessions:concessions.value}]=await Promise.all([requestApi(`/api/v1/lots/${props.lot.lotId}/geofence`),requestApi('/api/v1/geofences')]);reconcilePending(scope(),data.value.history.map(e=>e.operationId));pending.value=pendingOperations(scope()).filter(p=>p.action.startsWith('geo:'));if(data.value.capture&&!latitude.value){latitude.value=data.value.capture.location?.latitude??'';longitude.value=data.value.capture.location?.longitude??'';concessionId.value=data.value.capture.concessionId??'';}}catch(e){error.value=e.message;}}
watch(()=>[props.lot.lotId,props.lot.version,props.online],load,{immediate:true});
async function check(){busy.value=true;error.value='';try{await submitOperation(`/api/v1/lots/${props.lot.lotId}/geofence`,{expectedVersion:props.lot.version,concessionId:concessionId.value||null,location:latitude.value!==''&&longitude.value!==''?{latitude:Number(latitude.value),longitude:Number(longitude.value)}:null,reason:reason.value},scope(),'geo:check');notice.value='Comprobación conservada en el historial. La ubicación no aprueba por sí sola la evidencia de origen.';await load();emit('refresh');}catch(e){error.value=e.message;pending.value=pendingOperations(scope()).filter(p=>p.action.startsWith('geo:'));}finally{busy.value=false;}}
async function register(){busy.value=true;error.value='';try{const polygon=registry.vertices.split('\n').filter(line=>line.trim()).map(line=>{const values=line.split(',').map(v=>Number(v.trim()));if(values.length!==2||values.some(v=>!Number.isFinite(v)))throw Error('Cada vértice debe tener latitud, longitud');return {latitude:values[0],longitude:values[1]};});const result=await submitOperation('/api/v1/geofences',{...registry,polygon,vertices:undefined},scope(),'geo:register');concessionId.value=result.concessionId;notice.value='Polígono autorizado registrado con su fuente y responsable.';await load();}catch(e){error.value=e.message;pending.value=pendingOperations(scope()).filter(p=>p.action.startsWith('geo:'));}finally{busy.value=false;}}
async function retry(attempt){try{await retryOperation(attempt);await load();emit('refresh');}catch(e){error.value=e.message;}}
</script>
<template><section class="lot-operations" aria-label="Comprobación de ubicación"><h3>Comprobación de ubicación</h3><p v-if="error" class="alert error" role="alert">{{error}}</p><p v-if="notice" class="alert" role="status">{{notice}}</p><p v-if="data" :class="['alert',data.status==='Outside'?'error':'']">{{labels[data.status]}}</p><p class="muted">Una declaración sin ubicación o sin concesión verificable permanece pendiente. Esta comprobación no sustituye la revisión de documentos.</p><p v-for="attempt in pending" :key="attempt.key" class="alert">Comprobación sin confirmar. <button @click="retry(attempt)">Reintentar ubicación</button></p>
 <form v-if="can('evidence.review')" @submit.prevent="check"><div class="formrow"><label>Latitud de origen<input v-model="latitude" type="number" step="any" min="-90" max="90" /></label><label>Longitud de origen<input v-model="longitude" type="number" step="any" min="-180" max="180" /></label></div><label>Concesión autorizada<select v-model="concessionId"><option value="">Sin fuente verificable</option><option v-for="c in concessions" :key="c.id" :value="c.id">{{c.name}} · {{c.authorizationRef}}</option></select></label><label>Motivo de comprobación de ubicación<input v-model="reason" required /></label><button :disabled="busy||!online">Comprobar ubicación</button></form>
 <details v-if="can('geofences.manage')"><summary>Registrar polígono autorizado</summary><form @submit.prevent="register"><label>Nombre de concesión<input v-model="registry.name" required /></label><label>Fuente cartográfica verificable<input v-model="registry.source" required /></label><label>Documento de autorización de concesión<input v-model="registry.authorizationRef" required /></label><label>Vértices de concesión<textarea v-model="registry.vertices" rows="5" required placeholder="Latitud, longitud en cada línea" /></label><label class="checkbox-label"><input v-model="registry.confirmAuthorization" type="checkbox" required /> Revisé la fuente y la autorización de este polígono</label><button :disabled="busy||!online">Guardar concesión autorizada</button></form></details>
 <ol v-if="data" class="history-list"><li v-for="event in data.history" :key="event.operationId"><strong>{{labels[event.status]}}</strong><p>{{event.source??'Sin fuente verificable'}} · {{event.authorizationRef??'Sin autorización identificada'}}</p><p>{{event.reason}} · {{new Date(event.occurredAt).toLocaleString('es-PE')}}</p></li></ol>
</section></template>
